const item = $input.first().json;

let pdfBase64 = null;
let pdfName = null;

for (let i = 0; i < 10; i++) {
  const key = `attachment_${i}`;
  if (!item[key]) break;
  const att = item[key];
  const name = att.name || att.filename || '';
  const mime = att.mimeType || att.contentType || '';
  if (name.toLowerCase().endsWith('.pdf') || mime.includes('pdf')) {
    pdfBase64 = att.data || att.content;
    pdfName = name;
    break;
  }
}

if (!pdfBase64) {
  return [{ json: { error: true, message: 'No PDF attachment found', subject: item.subject, date: item.date } }];
}

return [{ json: { pdf_base64: pdfBase64, pdf_name: pdfName, email_subject: item.subject, email_date: item.date } }];

const item = $input.first().json;

if (item.error) return [{ json: item }];

const pdfBase64 = item.pdf_base64;
const pdfBuffer = Buffer.from(pdfBase64, 'base64');

let pdfText = '';
try {
  const pdfParse = require('pdf-parse');
  const data = await pdfParse(pdfBuffer);
  pdfText = data.text;
} catch (e) {
  return [{ json: { error: true, message: `PDF parse failed: ${e.message}`, email_subject: item.email_subject, email_date: item.email_date } }];
}

if (!pdfText || pdfText.trim().length < 20) {
  return [{ json: { error: true, message: 'PDF text extraction returned empty content', email_subject: item.email_subject, email_date: item.email_date } }];
}

return [{ json: { ...item, pdf_text: pdfText } }];

