const item = $input.first().json;

// Handle upstream errors passed through
if (item.error) return [{ json: item }];

// Groq HTTP response shape: { choices: [{ message: { content: '...' } }] }
const rawText = item.choices?.[0]?.message?.content || '';

if (!rawText) {
  return [{ json: { error: true, message: 'Groq returned empty response' } }];
}

let parsed;
try {
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  return [{ json: { error: true, message: 'Could not parse Groq JSON response', raw: rawText } }];
}

const firstName = (parsed.first_name || '').trim();
const lastName = (parsed.last_name || '').trim();
const breakerName = (parsed.breaker_name || '').trim();
const breakerEmail = (parsed.breaker_email || '').trim();

if (!firstName || !breakerName) {
  return [{ json: { error: true, message: `Missing required fields — first_name: '${firstName}', breaker_name: '${breakerName}'`, parsed } }];
}

// Password formula: FirstName_BreakerName_L2-2026!
const firstSlug = firstName.replace(/\s+/g, '');
const breakerSlug = breakerName.replace(/\s+/g, '');
const password = `${firstSlug}_${breakerSlug}_L2-2026!`;

return [{
  json: {
    success: true,
    first_name: firstName,
    last_name: lastName,
    breaker_name: breakerName,
    breaker_email: breakerEmail,
    password: password,
    generated_at: new Date().toISOString()
  }
}];

